// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // current owner (deployer) transfers ownership to the fuzzed actor
        c.transferOwnership(newOwner);
        // the new owner initialises the distribution
        vm.prank(newOwner);
        c.NETM();
        // General rule: after NETM(), the owner's balance equals totalDistributed
        assertTrue(c.balanceOf(newOwner) == c.totalDistributed());
    }
}

