// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address k) public {
        vm.assume(actor != address(this)); // deployer is the original owner

        bool ok = true;
        vm.prank(actor);
        try c.NETM() { ok = true; } catch { ok = false; }

        // Universal rule: after a NETM call initiated by a non-owner actor,
        // the balance at ANY address k is unchanged (still zero), because the
        // call must revert and distribute nothing to anyone.
        assertTrue(c.balanceOf(k) == 0);
    }
}

