// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        c = new C();
        deployer = msg.sender;
    }

    function testFuzz_property(address newOwner, address actor) public {
        vm.assume(newOwner != address(0));
        vm.assume(actor != newOwner);

        // current owner (deployer) hands ownership to a fuzzed newOwner
        vm.prank(deployer);
        c.transferOwnership(newOwner);

        // a non-owner caller attempts NETM(); in the reference it must revert
        vm.prank(actor);
        bool ok;
        try c.NETM() { ok = true; } catch { ok = false; }

        assertTrue(!ok, "non-owner NETM call must fail");
    }
}
